const demos=[{id:'base',html:'<div class="demo-caption"><span>프로덕트 디자이너 · 기본</span><span>문서 예시</span></div><article class="demo-sheet"><h3>김하윤의 이력서</h3><h4>소개</h4><p>복잡한 문제를 이해하기 쉬운 경험으로 바꾸는 프로덕트 디자이너입니다. 사용자 리서치부터 출시 후 개선까지 제품의 전 과정을 연결합니다.</p><div class="demo-tags"><span>소개</span><span>경력</span><span>학력</span><span>스킬</span></div></article>'},{id:'tailored',html:'<div class="demo-caption"><span>지원용으로 복제</span><span>예시</span></div><article class="demo-sheet"><h3>커머스 제품팀 지원용</h3><h4>소개</h4><p>구매 여정의 마찰을 찾아 개선하는 프로덕트 디자이너입니다. 사용자 관찰과 실험 결과를 제품 의사결정에 연결합니다.</p><div class="demo-tags"><span>기본 이력서 보존</span><span>지원용 문서 별도 편집</span></div></article>'},{id:'compare',html:'<div class="demo-caption"><span>달라진 항목: 소개</span><span>버전 비교 예시</span></div><div class="compare-demo"><article class="demo-sheet"><h3>기본 이력서</h3><p>복잡한 문제를 이해하기 쉬운 경험으로 바꾸는 프로덕트 디자이너입니다.</p></article><article class="demo-sheet"><h3>커머스 지원용</h3><p>구매 여정의 마찰을 찾아 개선하는 프로덕트 디자이너입니다.</p></article></div>'}];
const panel=document.querySelector('#demo-panel');
if(panel){panel.innerHTML=demos[0].html;document.querySelectorAll('[data-demo]').forEach(control=>{control.addEventListener('click',()=>{if(!(control instanceof HTMLButtonElement))return;const demo=demos.find(item=>item.id===control.dataset.demo);if(!demo)return;panel.innerHTML=demo.html;document.querySelectorAll('[data-demo]').forEach(item=>item.setAttribute('aria-pressed',String(item===control)));});});}
